27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "birth_date")
58	    private LocalDate birthDate;
59	
60	    @Column(name = "customer_code")
61	    private String customerCode;
62	
63	    @Column(name = "household_id")
64	    private String householdId;
65	
66	    @Column(name = "namesake_count")
67	    private Integer namesakeCount;
68	
69	    @Column(name = "membership_number")
70	    private String membershipNumber;
71	
72	    @Column(name = "bulk_signup_warning")
73	    private Boolean bulkSignupWarning;
74	
75	    @Column(name = "household_size")
76	    private Integer householdSize;
77	
78	    @Column(name = "postcode")
79	    private String postcode;
80	
81	    @Column(name = "possible_duplicate_of")
82	    private Integer possibleDuplicateOf;
83	
84	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
85	    private Set<Pet> pets;
86	
87	    public String getAddress() {
88	        return this.address;
89	    }
90	
91	    public void setAddress(String address) {
92	        this.address = address;
93	    }
94	
95	    public String getCity() {
96	        return this.city;
97	    }
98	
99	    public void setCity(String city) {
100	        this.city = city;
101	    }
102	
103	    public String getTelephone() {
104	        return this.telephone;
105	    }
106	
107	    public void setTelephone(String telephone) {
108	        this.telephone = telephone;
109	    }
110	
111	    /**
112	     * Return this owner's stored E.164 {@link #getTelephone() telephone} formatted for human display
113	     * as the calling code, a space, then the national digits grouped in threes, e.g.
114	     * {@code "+61 412 345 678"}. See {@link TelephoneFormatter}.
115	     */
116	    @Transient
117	    public String getTelephoneDisplay() {
118	        return TelephoneFormatter.toDisplay(this.telephone);
119	    }
120	
121	    public String getEmail() {
122	        return this.email;
123	    }
124	
125	    public void setEmail(String email) {
126	        this.email = email;
127	    }
128	
129	    public LocalDate getRegistrationDate() {
130	        return this.registrationDate;
131	    }
132	
133	    public void setRegistrationDate(LocalDate registrationDate) {
134	        this.registrationDate = registrationDate;
135	    }
136	
137	    public LocalDate getBirthDate() {
138	        return this.birthDate;
139	    }
140	
141	    public void setBirthDate(LocalDate birthDate) {
142	        this.birthDate = birthDate;
143	    }
144	
145	    public String getCustomerCode() {
146	        return this.customerCode;
147	    }
148	
149	    public void setCustomerCode(String customerCode) {
150	        this.customerCode = customerCode;
151	    }
152	
153	    public String getHouseholdId() {
154	        return this.householdId;
155	    }
156	
157	    public void setHouseholdId(String householdId) {
158	        this.householdId = householdId;
159	    }
160	
161	    public Integer getNamesakeCount() {
162	        return this.namesakeCount;
163	    }
164	
165	    public void setNamesakeCount(Integer namesakeCount) {
166	        this.namesakeCount = namesakeCount;
167	    }
168	
169	    public String getMembershipNumber() {
170	        return this.membershipNumber;
171	    }
172	
173	    public void setMembershipNumber(String membershipNumber) {
174	        this.membershipNumber = membershipNumber;
175	    }
176	
177	    /**
178	     * Whether this owner was created after more than 80 owners had already been registered on the
179	     * same day, flagging an unusually high-volume ("bulk") signup. Captured once at creation.
180	     */
181	    public Boolean getBulkSignupWarning() {
182	        return this.bulkSignupWarning;
183	    }
184	
185	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
186	        this.bulkSignupWarning = bulkSignupWarning;
187	    }
188	
189	    /**
190	     * The number of owners in this owner's household (owners sharing the same {@code householdId},
191	     * counting this owner) captured once at creation.
192	     */
193	    public Integer getHouseholdSize() {
194	        return this.householdSize;
195	    }
196	
197	    public void setHouseholdSize(Integer householdSize) {
198	        this.householdSize = householdSize;
199	    }
200	
201	    /**
202	     * This owner's 4-digit postcode, or {@code null} when none was supplied. When present it is
203	     * validated against the owner's city region at creation (see {@code PostcodeValidator}).
204	     */
205	    public String getPostcode() {
206	        return this.postcode;
207	    }
208	
209	    public void setPostcode(String postcode) {
210	        this.postcode = postcode;
211	    }
212	
213	    /**
214	     * The id of an existing owner this owner was flagged as a possible (soft) duplicate of at
215	     * creation, or {@code null} when none. Because owners sharing a last name and postcode now form
216	     * the same household — rejected as a household duplicate unless declared via {@code sharesHousehold},
217	     * and a declared member is not a suspected duplicate — this is not populated at creation.
218	     * Captured once at creation.
219	     */
220	    public Integer getPossibleDuplicateOf() {
221	        return this.possibleDuplicateOf;
222	    }
223	
224	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
225	        this.possibleDuplicateOf = possibleDuplicateOf;
226	    }
227	
228	    /**
229	     * Whether this owner was flagged as a possible (soft) duplicate of an existing owner at creation,
230	     * i.e. whether {@link #getPossibleDuplicateOf()} is set.
231	     */
232	    @Transient
233	    public Boolean getPossibleDuplicate() {
234	        return this.possibleDuplicateOf != null;
235	    }
236	
237	    /**
238	     * Return this owner's name formatted for display as {@code "LastName, FirstName"}.
239	     */
240	    @Transient
241	    public String getDisplayName() {
242	        return this.getLastName() + ", " + this.getFirstName();
243	    }
244	
245	    /**
246	     * Return this owner's initials as the upper-cased first letters of the first and last
247	     * name, dot-separated with a trailing dot, e.g. {@code "J.S."}.
248	     */
249	    @Transient
250	    public String getInitials() {
251	        return initial(this.getFirstName()) + initial(this.getLastName());
252	    }
253	
254	    private static String initial(String name) {
255	        return Character.toUpperCase(name.charAt(0)) + ".";
256	    }
257	
258	    /** The membership level every owner starts at on creation. */
259	    private static final int BASE_MEMBERSHIP_LEVEL = 1;
260	
261	    /** The highest membership level derivable at creation; level 4 is reserved for tenure. */
262	    private static final int MAX_MEMBERSHIP_LEVEL = 3;
263	
264	    /**
265	     * Return this owner's membership level, a number from 1 to 3 derived at creation: every owner
266	     * starts at {@value #BASE_MEMBERSHIP_LEVEL}; add 1 when an email address is present; add 1 when
267	     * the owner has no namesakes ({@code namesakeCount} is 0); capped at
268	     * {@value #MAX_MEMBERSHIP_LEVEL} (level 4 is reserved for tenure).
269	     */
270	    @Transient
271	    public Integer getMembershipLevel() {
272	        int level = BASE_MEMBERSHIP_LEVEL;
273	        if (hasEmail()) {
274	            level++;
275	        }
276	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
277	            level++;
278	        }
279	        return Math.min(level, MAX_MEMBERSHIP_LEVEL);
280	    }
281	
282	    /** Whether this owner has a usable email address (present and not blank). */
283	    private boolean hasEmail() {
284	        return this.email != null && !this.email.isBlank();
285	    }
286	
287	    /**
288	     * Return this owner's preferred contact channel: {@code "EMAIL"} when an email address is
289	     * present, otherwise {@code "PHONE"}.
290	     */
291	    @Transient
292	    public String getContactPreference() {
293	        return hasEmail() ? "EMAIL" : "PHONE";
294	    }
295	
296	    /**
297	     * Return this owner's age band derived from the {@code birthDate} as of the
298	     * {@code registrationDate}, or {@code null} when no birth date is known.
299	     */
300	    @Transient
301	    public AgeBand getAgeBand() {
302	        if (this.birthDate == null || this.registrationDate == null) {
303	            return null;
304	        }
305	        return AgeBand.asOf(this.birthDate, this.registrationDate);
306	    }
307	
308	    /**
309	     * Return this owner's locality: the region segment of the {@code customerCode} (the leading
310	     * {@code <REGION>} of {@code <REGION>-<HASH8>}), which is fixed at creation from the postcode
311	     * (preferred, matched against the known region ranges) falling back to the city-to-region table,
312	     * or {@code "UNKNOWN"} when neither yields a region. Before the customer code is assigned the
313	     * region is resolved directly from the postcode and city.
314	     */
315	    @Transient
316	    public String getLocality() {
317	        if (this.customerCode == null) {
318	            return LocalityResolver.regionFor(this.postcode, this.city);
319	        }
320	        int separator = this.customerCode.indexOf('-');
321	        return separator < 0 ? this.customerCode : this.customerCode.substring(0, separator);
322	    }
323	
324	    /**
325	     * Return this owner's check digit: the single Luhn check digit computed over the digits of the
326	     * {@code customerCode}.
327	     */
328	    @Transient
329	    public Integer getCheckDigit() {
330	        return this.customerCode == null ? null : LuhnCheckDigit.of(this.customerCode);
331	    }
332	
333	    /**
334	     * Return this owner's identity key, the single derived value all duplicate detection is based
335	     * on: the normalized telephone, email and household id joined with {@code '|'} as
336	     * {@code telephone + "|" + email + "|" + householdId}, with each absent component rendered as
337	     * the empty string. Two owners are duplicates only when their whole identity keys are equal;
338	     * because the telephone is part of the key, members of one household (same {@code householdId})
339	     * with different telephones have distinct keys and are not duplicates.
340	     */
341	    @Transient
342	    public String getIdentityKey() {
343	        return keyPart(this.telephone) + "|" + keyPart(this.email) + "|" + keyPart(this.householdId);
344	    }
345	
346	    private static String keyPart(String value) {
347	        return value == null ? "" : value;
348	    }
349	
350	    protected Set<Pet> getPetsInternal() {
351	        if (this.pets == null) {
352	            this.pets = new HashSet<>();
353	        }
354	        return this.pets;
355	    }
356	
357	    protected void setPetsInternal(Set<Pet> pets) {
358	        this.pets = pets;
359	    }
360	
361	    public List<Pet> getPets() {
362	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
363	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
364	        return Collections.unmodifiableList(sortedPets);
365	    }
366	
367	    public void setPets(List<Pet> pets) {
368	        this.pets = new HashSet<>(pets);
369	    }
370	
371	    public void addPet(Pet pet) {
372	        getPetsInternal().add(pet);
373	        pet.setOwner(this);
374	    }
375	
376	    /**
377	     * Return the Pet with the given name, or null if none found for this Owner.
378	     *
379	     * @param name to test
380	     * @return true if pet name is already in use
381	     */
382	    public Pet getPet(String name) {
383	        return getPet(name, false);
384	    }
385	
386	    /**
387	     * Return the Pet with the given name, or null if none found for this Owner.
388	     *
389	     * @param name to test
390	     * @return true if pet name is already in use
391	     */
392	    public Pet getPet(String name, boolean ignoreNew) {
393	        name = name.toLowerCase();
394	        for (Pet pet : getPetsInternal()) {
395	            if (!ignoreNew || !pet.isNew()) {
396	                String compName = pet.getName();
397	                compName = compName.toLowerCase();
398	                if (compName.equals(name)) {
399	                    return pet;
400	                }
401	            }
402	        }
403	        return null;
404	    }
405	
406	    public Pet getPet(Integer petId) {
407	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
408	    }
409	
410	    @Override
411	    public String toString() {
412	        return new ToStringCreator(this)
413	
414	            .append("id", this.getId())
415	            .append("new", this.isNew())
416	            .append("lastName", this.getLastName())
417	            .append("firstName", this.getFirstName())
418	            .append("address", this.address)
419	            .append("city", this.city)
420	            .append("telephone", this.telephone)
421	            .append("email", this.email)
422	            .append("registrationDate", this.registrationDate)
423	            .toString();
424	    }
425	}
